spec fn selected(a: &[i64], b: &[i64], i: usize) -> bool {
    a.len() == b.len() && i < a.len() && (forall|k: usize| k < i ==> #[trigger] a[k] == b[k]) && (forall|j: usize| i <= j && j < a.len() ==> a[i] <= #[trigger] a[j])
}

#[effects(pure)]
#[uses(ordered, idx2, selected, arr::min_ok, arr::same_len)]
fn run(a: &mut [i64], i: usize) -> ()
    requires ordered(a, i),
    ensures selected(a, old(a), i),
{
    let j: usize = abs_small(a, i);
    arr::min2(a, i, j);
}

